import{_ as e,c as n,o as t,ag as s}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Authentik Installation","description":"","frontmatter":{"title":"Authentik Installation"},"headers":[],"relativePath":"infrastructure/authentik-installation.md","filePath":"infrastructure/authentik-installation.md","lastUpdated":null}'),i={name:"infrastructure/authentik-installation.md"};function o(l,a,r,p,u,c){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="authentik-installation" tabindex="-1">Authentik Installation <a class="header-anchor" href="#authentik-installation" aria-label="Permalink to &quot;Authentik Installation&quot;">​</a></h1><h2 id="about-authentik" tabindex="-1">About Authentik <a class="header-anchor" href="#about-authentik" aria-label="Permalink to &quot;About Authentik&quot;">​</a></h2><p>Authentik is an open-source identity provider that integrates seamlessly into your applications. It is designed to provide secure authentication and authorization services for your users.</p><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><ul><li><p>A host with at least 2 CPU cores and 2 GB of RAM</p></li><li><p>Docker</p></li><li><p>Docker Compose (Compose v2 is recommended, see <a href="https://docs.docker.com/compose/install/" target="_blank" rel="noreferrer">here for instructions on how to upgrade</a></p></li></ul><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><p>To install Authentik using Docker Compose, follow these steps:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>wget https://goauthentik.io/docker-compose.yml</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo apt-get install -y pwgen</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;PG_PASS=$(pwgen -s 40 1)&quot; &gt;&gt; .env</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;AUTHENTIK_SECRET_KEY=$(pwgen -s 50 1)&quot; &gt;&gt; .env</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;AUTHENTIK_ERROR_REPORTING__ENABLED=true&quot; &gt;&gt; .env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="run-authentik-compose-file" tabindex="-1">Run Authentik Compose File <a class="header-anchor" href="#run-authentik-compose-file" aria-label="Permalink to &quot;Run Authentik Compose File&quot;">​</a></h3><p>This command initially installs Authentik and is also used to update settings and configurations:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>docker-compose pull</span></span>
<span class="line"><span>docker-compose up -d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="initial-setup" tabindex="-1">Initial Setup <a class="header-anchor" href="#initial-setup" aria-label="Permalink to &quot;Initial Setup&quot;">​</a></h3><p>To start the initial setup, navigate to: <code>http://&amp;lt;your server&#39;s IP or hostname&amp;gt;:9443/if/flow/initial-setup/</code>.</p><h3 id="benefits-of-self-hosting" tabindex="-1">Benefits of Self-Hosting <a class="header-anchor" href="#benefits-of-self-hosting" aria-label="Permalink to &quot;Benefits of Self-Hosting&quot;">​</a></h3><p>Self-hosting Authentik has its advantages and disadvantages.</p><h3 id="positives" tabindex="-1">Positives <a class="header-anchor" href="#positives" aria-label="Permalink to &quot;Positives&quot;">​</a></h3><ul><li><p>Full control over your authentication processes and user data.</p></li><li><p>Ability to customize features to suit your community&#39;s needs.</p></li><li><p>Enhanced privacy and security since data does not reside on third-party servers.</p></li><li><p>Privacy is improved since data is not stored on third-party servers.</p></li><li><p>Cost-effective compared to paid services which may charge per user.</p></li><li><p>Automations can be set up to manage user accounts and permissions.</p></li></ul><h3 id="negatives" tabindex="-1">Negatives <a class="header-anchor" href="#negatives" aria-label="Permalink to &quot;Negatives&quot;">​</a></h3><ul><li><p>Requires maintenance, including updates and backups.</p></li><li><p>Initial setup and configuration may be complex for some users.</p></li><li><p>Needs a reliable host with sufficient resources.</p></li><li><p>Security may be compromised if not properly configured and the identity provider is a large target for attackers.</p></li></ul><h3 id="community-building" tabindex="-1">Community Building <a class="header-anchor" href="#community-building" aria-label="Permalink to &quot;Community Building&quot;">​</a></h3><p>Self-hosting Authentik can significantly contribute to community building by providing a secure and customizable authentication solution. It allows community moderators to manage user accounts effectively, creating a trustworthy environment for all members.</p><p>For example, this community-made app allows moderators to use specific functions from Authentik: <a href="https://github.com/irregularchat/authentik-account-creation" target="_blank" rel="noreferrer">Authentik Account Creation</a>.</p>`,22)])])}const m=e(i,[["render",o]]);export{h as __pageData,m as default};
